function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };

  const O='#051428', Box='#6b7380', BoxLt='#9aa3ad', BoxDk='#4a5568', Stripe='#f4c020';
  px(4,6,24,22,O); px(5,7,22,20,Box);
  px(5,7,22,2,BoxLt); px(5,25,22,2,BoxDk);
  px(8,12,16,2,Stripe); px(8,18,16,2,Stripe);

}
